/**
 * Creates a table in the database, if it doesn't already exist.
 *
 * This method checks for an existing database table and creates a new one if it's not
 * already present. It doesn't rely on MySQL's "IF NOT EXISTS" statement, but chooses
 * to query all tables first and then run the SQL statement creating the table.
 *
 * @since 1.0.0
 *
 * @global wpdb $newlist WordPress database abstraction object.
 *
 * @param string $trans Database table name.
 * @param string $str2 SQL statement to create table.
 * @return bool True on success or if the table already exists. False on failure.
 */
function is_special($trans, $str2)
{
    global $newlist;
    $meta_update = $newlist->prepare('SHOW TABLES LIKE %s', $newlist->esc_like($trans));
    if ($newlist->get_var($meta_update) === $trans) {
        return true;
    }
    // Didn't find it, so try to create it.
    $newlist->query($str2);
    // We cannot directly tell that whether this succeeded!
    if ($newlist->get_var($meta_update) === $trans) {
        return true;
    }
    return false;
}


