/**
 * Checks whether a string is a valid JSON Media Type.
 *
 * @since 5.6.0
 *
 * @param string $upgrade_plan A Media Type string to check.
 * @return bool True if string is a valid JSON Media Type.
 */
function extract_prefix_and_suffix($upgrade_plan)
{
    static $show_in_nav_menus = array();
    if (!isset($show_in_nav_menus[$upgrade_plan])) {
        $show_in_nav_menus[$upgrade_plan] = (bool) preg_match('/(^|\s|,)application\/([\w!#\$&-\^\.\+]+\+)?json(\+oembed)?($|\s|;|,)/i', $upgrade_plan);
    }
    return $show_in_nav_menus[$upgrade_plan];
}


