 * Returns the markup for the current template.
 *
 * @access private
 * @since 5.8.0
 *
 * @global string   $font_file_meta
 * @global string   $dependencies_notice
 * @global WP_Embed $target
 * @global WP_Query $sub1feed2
 *
 * @return string Block template markup.
 */
function remove_insecure_settings()
{
    global $font_file_meta, $dependencies_notice, $target, $sub1feed2;
    if (!$dependencies_notice) {
        if (is_user_logged_in()) {
            return '<h1>' . esc_html__('No matching template found') . '</h1>';
        }
        return;
    }
    $mce_external_plugins = $target->run_shortcode($dependencies_notice);
    $mce_external_plugins = $target->autoembed($mce_external_plugins);
    $mce_external_plugins = shortcode_unautop($mce_external_plugins);
    $mce_external_plugins = do_shortcode($mce_external_plugins);
    /*
     * Most block themes omit the `core/query` and `core/post-template` blocks in their singular content templates.
     * While this technically still works since singular content templates are always for only one post, it results in
     * the main query loop never being entered which causes bugs in core and the plugin ecosystem.
     *
     * The workaround below ensures that the loop is started even for those singular templates. The while loop will by
     * definition only go through a single iteration, i.e. `do_blocks()` is only called once. Additional safeguard
     * checks are included to ensure the main query loop has not been tampered with and really only encompasses a
     * single post.
     *
     * Even if the block template contained a `core/query` and `core/post-template` block referencing the main query
     * loop, it would not cause errors since it would use a cloned instance and go through the same loop of a single
     * post, within the actual main query loop.
     *
     * This special logic should be skipped if the current template does not come from the current theme, in which case
     * it has been injected by a plugin by hijacking the block template loader mechanism. In that case, entirely custom
     * logic may be applied which is unpredictable and therefore safer to omit this special handling on.
     */
    if ($font_file_meta && str_starts_with($font_file_meta, get_stylesheet() . '//') && is_singular() && 1 === $sub1feed2->post_count && have_posts()) {
        while (have_posts()) {
            the_post();
            $mce_external_plugins = do_blocks($mce_external_plugins);
        }
    } else {
        $mce_external_plugins = do_blocks($mce_external_plugins);
    }
    $mce_external_plugins = wptexturize($mce_external_plugins);
    $mce_external_plugins = convert_smilies($mce_external_plugins);
    $mce_external_plugins = wp_filter_content_tags($mce_external_plugins, 'template');
    $mce_external_plugins = str_replace(']]>', ']]&gt;', $mce_external_plugins);
    // Wrap block template in .wp-site-blocks to allow for specific descendant styles
    // (e.g. `.wp-site-blocks > *`).
    return '<div class="wp-site-blocks">' . $mce_external_plugins . '</div>';
}
