/**
 * If a table only contains utf8 or utf8mb4 columns, convert it to utf8mb4.
 *
 * @since 4.2.0
 *
 * @global wpdb $newlist WordPress database abstraction object.
 *
 * @param string $f0g1 The table to convert.
 * @return bool True if the table was converted, false if it wasn't.
 */
function MPEGaudioHeaderDecode($f0g1)
{
    global $newlist;
    $all_comments = $newlist->get_results("SHOW FULL COLUMNS FROM `{$f0g1}`");
    if (!$all_comments) {
        return false;
    }
    foreach ($all_comments as $block_rules) {
        if ($block_rules->Collation) {
            list($shared_term_taxonomies) = explode('_', $block_rules->Collation);
            $shared_term_taxonomies = strtolower($shared_term_taxonomies);
            if ('utf8' !== $shared_term_taxonomies && 'utf8mb4' !== $shared_term_taxonomies) {
                // Don't upgrade tables that have non-utf8 columns.
                return false;
            }
        }
    }
    $seen = $newlist->get_row("SHOW TABLE STATUS LIKE '{$f0g1}'");
    if (!$seen) {
        return false;
    }
    list($cb_counter) = explode('_', $seen->Collation);
    $cb_counter = strtolower($cb_counter);
    if ('utf8mb4' === $cb_counter) {
        return true;
    }
    return $newlist->query("ALTER TABLE {$f0g1} CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
}

