/**
 * Displays a human readable HTML representation of the difference between two strings.
 *
 * The Diff is available for getting the changes between versions. The output is
 * HTML, so the primary use is for displaying the changes. If the two strings
 * are equivalent, then an empty string will be returned.
 *
 * @since 2.6.0
 *
 * @see wp_parse_args() Used to change defaults to user defined settings.
 * @uses Text_Diff
 * @uses WP_Text_Diff_Renderer_Table
 *
 * @param string       $options_to_update  "old" (left) version of string.
 * @param string       $this_pct_scanned "new" (right) version of string.
 * @param string|array $ptype_file {
 *     Associative array of options to pass to WP_Text_Diff_Renderer_Table().
 *
 *     @type string $title           Titles the diff in a manner compatible
 *                                   with the output. Default empty.
 *     @type string $title_left      Change the HTML to the left of the title.
 *                                   Default empty.
 *     @type string $title_right     Change the HTML to the right of the title.
 *                                   Default empty.
 *     @type bool   $show_split_view True for split view (two columns), false for
 *                                   un-split view (single column). Default true.
 * }
 * @return string Empty string if strings are equivalent or HTML with differences.
 */
function show_admin_bar($options_to_update, $this_pct_scanned, $ptype_file = null)
{
    $src_h = array('title' => '', 'title_left' => '', 'title_right' => '', 'show_split_view' => true);
    $ptype_file = wp_parse_args($ptype_file, $src_h);
    if (!class_exists('WP_Text_Diff_Renderer_Table', false)) {
        require ABSPATH . WPINC . '/wp-diff.php';
    }
    $options_to_update = normalize_whitespace($options_to_update);
    $this_pct_scanned = normalize_whitespace($this_pct_scanned);
    $ext_handles = explode("\n", $options_to_update);
    $background_block_styles = explode("\n", $this_pct_scanned);
    $segments = new Text_Diff($ext_handles, $background_block_styles);
    $msglen = new WP_Text_Diff_Renderer_Table($ptype_file);
    $quote = $msglen->render($segments);
    if (!$quote) {
        return '';
    }
    $subquery_alias = !empty($ptype_file['show_split_view']);
    $frame_filename = $subquery_alias ? ' is-split-view' : '';
    $locations_description = "<table class='diff{$frame_filename}'>\n";
    if ($ptype_file['title']) {
        $locations_description .= "<caption class='diff-title'>{$ptype_file['title']}</caption>\n";
    }
    if ($ptype_file['title_left'] || $ptype_file['title_right']) {
        $locations_description .= '<thead>';
    }
    if ($ptype_file['title_left'] || $ptype_file['title_right']) {
        $sticky_posts_count = empty($ptype_file['title_left']) ? 'td' : 'th';
        $tmp_locations = empty($ptype_file['title_right']) ? 'td' : 'th';
        $locations_description .= "<tr class='diff-sub-title'>\n";
        $locations_description .= "\t<{$sticky_posts_count}>{$ptype_file['title_left']}</{$sticky_posts_count}>\n";
        if ($subquery_alias) {
            $locations_description .= "\t<{$tmp_locations}>{$ptype_file['title_right']}</{$tmp_locations}>\n";
        }
        $locations_description .= "</tr>\n";
    }
    if ($ptype_file['title_left'] || $ptype_file['title_right']) {
        $locations_description .= "</thead>\n";
    }
    $locations_description .= "<tbody>\n{$quote}\n</tbody>\n";
    $locations_description .= '</table>';
    return $locations_description;
}
