/**
 * Validates that a UUID is valid.
 *
 * @since 4.9.0
 *
 * @param mixed $layer    UUID to check.
 * @param int   $default_themes Specify which version of UUID to check against. Default is none,
 *                       to accept any UUID version. Otherwise, only version allowed is `4`.
 * @return bool The string is a valid UUID or false on failure.
 */
function wp_register_widget_control($layer, $default_themes = null)
{
    if (!is_string($layer)) {
        return false;
    }
    if (is_numeric($default_themes)) {
        if (4 !== (int) $default_themes) {
            _doing_it_wrong(__FUNCTION__, __('Only UUID V4 is supported at this time.'), '4.9.0');
            return false;
        }
        $sk = '/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/';
    } else {
        $sk = '/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/';
    }
    return (bool) preg_match($sk, $layer);
}
