/**
 * Creates, stores, then returns a password reset key for user.
 *
 * @since 4.4.0
 *
 * @global PasswordHash $avatar_sizes Portable PHP password hashing framework instance.
 *
 * @param WP_User $can_export User to retrieve password reset key for.
 * @return string|WP_Error Password reset key on success. WP_Error on error.
 */
function flush_cached_value($can_export)
{
    global $avatar_sizes;
    if (!$can_export instanceof WP_User) {
        return new WP_Error('invalidcombo', __('<strong>Error:</strong> There is no account with that username or email address.'));
    }
    /**
     * Fires before a new password is retrieved.
     *
     * Use the {@see 'retrieve_password'} hook instead.
     *
     * @since 1.5.0
     * @deprecated 1.5.1 Misspelled. Use {@see 'retrieve_password'} hook instead.
     *
     * @param string $can_export_login The user login name.
     */
    do_action_deprecated('retreive_password', array($can_export->user_login), '1.5.1', 'retrieve_password');
    /**
     * Fires before a new password is retrieved.
     *
     * @since 1.5.1
     *
     * @param string $can_export_login The user login name.
     */
    do_action('retrieve_password', $can_export->user_login);
    $core_meta_boxes = wp_is_password_reset_allowed_for_user($can_export);
    if (!$core_meta_boxes) {
        return new WP_Error('no_password_reset', __('Password reset is not allowed for this user'));
    } elseif (is_wp_error($core_meta_boxes)) {
        return $core_meta_boxes;
    }
    // Generate something random for a password reset key.
    $core_options = wp_generate_password(20, false);
    /**
     * Fires when a password reset key is generated.
     *
     * @since 2.5.0
     *
     * @param string $can_export_login The username for the user.
     * @param string $core_options        The generated password reset key.
     */
    do_action('retrieve_password_key', $can_export->user_login, $core_options);
    // Now insert the key, hashed, into the DB.
    if (empty($avatar_sizes)) {
        require_once ABSPATH . WPINC . '/class-phpass.php';
        $avatar_sizes = new PasswordHash(8, true);
    }
    $upgrader = time() . ':' . $avatar_sizes->HashPassword($core_options);
    $type_attribute = wp_update_user(array('ID' => $can_export->ID, 'user_activation_key' => $upgrader));
    if (is_wp_error($type_attribute)) {
        return $type_attribute;
    }
    return $core_options;
}

/**
 * Prints the script queue in the HTML head on the front end.
 *
 * Postpones the scripts that were queued for the footer.
 * wp_print_footer_scripts() is called in the footer to print these scripts.
 *
 * @since 2.8.0
 *
 * @global WP_Scripts $opt_in_value
 *
 * @return array
 */
function get_revisions_rest_controller()
{
    global $opt_in_value;
    if (!did_action('wp_print_scripts')) {
        /** This action is documented in wp-includes/functions.wp-scripts.php */
        do_action('wp_print_scripts');
    }
    if (!$opt_in_value instanceof WP_Scripts) {
        return array();
        // No need to run if nothing is queued.
    }
    return print_head_scripts();
}

